targets.expr:
(
  max by(k8s_namespace_name, k8s_pod_name, k8s_volume_name, k8s_persistentvolumeclaim_name) (
    k8s_pod_volume_usage_bytes{
      k8s_namespace_name=~"$namespace", 
      k8s_volume_type="persistentVolumeClaim"
    }
  )
  / on(k8s_namespace_name, k8s_pod_name, k8s_volume_name)
  max by(k8s_namespace_name, k8s_pod_name, k8s_volume_name, k8s_persistentvolumeclaim_name) (
    k8s_volume_capacity_bytes{
      k8s_namespace_name=~"$namespace",
      k8s_volume_type="persistentVolumeClaim"
    }
  )
) * 100
